API_name: get_handball_scheduled_matches
Description:
{
  "description": "Daily match list including scheduled matches.\n\n**The data will return for only -+7 days period, so endpoint can be tested with date range of today - 7 days.**",
  "required_parameters": [
    {
      "name": "date",
      "type": "STRING",
      "description": "The date of the match. The format is {dd/MM/yyyy}. Match list data can be retrieved for only ± 7 days.",
      "default": "28/01/2021"
    }
  ],
  "optional_parameters": []
}

API_name: get_airlines
Description:
{
  "description": "Searches for airline information using various identifiers or name.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "icao",
      "type": "String",
      "description": "International Civil Aviation Organization (ICAO) 3-character airline code."
    },
    {
      "name": "iata",
      "type": "String",
      "description": "International Air Transport Association (IATA) 2-character airline code."
    },
    {
      "name": "name",
      "type": "String",
      "description": "Airline name. This parameter supports partial matching (e.g. United will match United Airlines)",
      "default": "Singapore Airlines"
    }
  ]
}

API_name: get_timezone_info
Description:
{
  "description": "The Stadia TZ Lookup API provides time zone information, as well as information about any special offset (such as DST) in effect based on the latest IANA TZDB. Note that this API may not be accurate for timestamps in the past and does not claim to report precise nautical times in the open ocean beyond territorial waters.",
  "required_parameters": [
    {
      "name": "lat",
      "type": "NUMBER",
      "description": "The latitude component of any point on land."
    }
  ],
  "optional_parameters": []
}

API_name: english_talking_get_answer
Description:
{
  "description": "This API aims to provide users with the possibility of conducting dialogues in English where the conversations and answers are registered and evaluated by the users themselves.",
  "required_parameters": [],
  "optional_parameters": [
    {
      "name": "status",
      "type": "STRING",
      "description": "approved or analyzing",
      "default": "approved"
    },
    {
      "name": "answer",
      "type": "STRING",
      "description": "Response to the initial speech of the dialogue",
      "default": "Hi, how are you?"
    },
    {
      "name": "_id",
      "type": "STRING",
      "description": "Unique dialog identifier (automatically generated)\n\n",
      "default": "5ec47b3d8958430d6a6d5898"
    },
    {
      "name": "speech",
      "type": "STRING",
      "description": "Speak in which the usuairio wants to get an answer",
      "default": "Hi"
    },
    {
      "name": "user",
      "type": "STRING",
      "description": "User who created the dialogue",
      "default": "5ec479048958430d6a6d5895"
    }
  ]
}

