API_name: gamerpower_filter_and_group_giveaways
Description:
{
  "description": "Filter and group platforms and giveaway types to get personalized results.",
  "required_parameters": [
    {
      "name": "platform",
      "type": "STRING",
      "description": "The gaming platform(s) to filter by. (e.g., epic-games-store, steam, android)",
      "default": "epic-games-store.steam.android"
    }
  ],
  "optional_parameters": [
    {
      "name": "type",
      "type": "STRING",
      "description": "The type of giveaway to filter by. (e.g., game, loot)",
      "default": "game.loot"
    }
  ]
}

